const now = ctx.now();
const limit = Number("{{param.hours}}") * 3600 * 1000;
const rows = await ctx.db.list("{{param.ticket}}", { filter: [{ field: "{{param.status_field}}", op: "eq", value: "{{param.waiting_value}}" }], limit: 1000 });
const late: string[] = [];
for (const t of rows) {
  if (String(t["{{param.status_field}}"] ?? "") !== "{{param.waiting_value}}" || t["escalated_at"]) continue;
  const since = new Date(String(t["waiting_since"] ?? t["created_at"] ?? "")).getTime();
  if (!Number.isFinite(since) || now.getTime() - since < limit) continue;
  await ctx.db.update("{{param.ticket}}", String(t["id"]), { escalated_at: now.toISOString() });
  const label = String(t["{{param.ticket.label_field}}"] ?? t["id"]);
  const hours = Math.floor((now.getTime() - since) / 3600000);
  late.push(`${label} (waiting ${hours}h)`);
  const refField = "{{param.assignee_ref}}";
  const who = refField ? String(t[refField] ?? "") : "";
  if (who) {
    const person = await ctx.db.get("{{param.assignee_ref.ref}}", who);
    if (person && person["user_id"]) await ctx.notify({ title: `Reply overdue: ${label}`, body: `Waiting ${hours} hours. The deadline is {{param.hours}}.`, user: String(person["user_id"]) });
  }
}
if (late.length > 0) await ctx.notify({ title: `${late.length} past the {{param.hours}}h reply deadline`, body: late.slice(0, 15).join("\n"), role: "{{param.escalate_role}}" });
ctx.log(`escalated: ${late.length}`);
